import{_ as r,C as n,o as s,c as d,j as e,a,E as i,a3 as l}from"./chunks/framework.CZBGEXos.js";const m=JSON.parse('{"title":"Charts & drawing","description":"","frontmatter":{},"headers":[],"relativePath":"en/customize/chart-colors.md","filePath":"en/customize/chart-colors.md"}'),h={name:"en/customize/chart-colors.md"};function c(g,t,b,p,u,y){const o=n("Screenshot");return s(),d("div",null,[t[0]||(t[0]=e("h1",{id:"charts-drawing",tabindex:"-1"},[a("Charts & drawing "),e("a",{class:"header-anchor",href:"#charts-drawing","aria-label":'Permalink to "Charts & drawing"'},"​")],-1)),t[1]||(t[1]=e("p",null,[a("These settings live in the "),e("strong",null,"Home"),a(" tab of the main window, under the "),e("strong",null,"Charts"),a(" section. They are global: every chart in every tool — Knives, Alerts, Analyzer, Monitor — uses them.")],-1)),i(o,{src:"colors-main",alt:"The Charts settings section in the Home tab",caption:"Home → Charts"}),t[2]||(t[2]=l('<h2 id="candle-colors" tabindex="-1">Candle colors <a class="header-anchor" href="#candle-colors" aria-label="Permalink to &quot;Candle colors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Bullish candle</strong></td><td>Color of candles that closed up</td><td><code>#9D9D9D</code></td></tr><tr><td><strong>Bearish candle</strong></td><td>Color of candles that closed down</td><td><code>#4A4A4A</code></td></tr></tbody></table><p>Both open a color picker. The change applies to every chart in the app at once, so a candle scheme you pick here follows you from a Knives thumbnail to a fullscreen Analyzer panel.</p><p>The defaults are deliberately neutral greys rather than green/red — the intent is that color in the interface means &quot;something crossed a threshold&quot; rather than &quot;price went up&quot;. If you&#39;d rather have conventional green/red candles, set them here.</p><h2 id="drawing-color" tabindex="-1">Drawing color <a class="header-anchor" href="#drawing-color" aria-label="Permalink to &quot;Drawing color&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Drawing color</strong></td><td>Color used by all five drawing tools</td><td>Falls back to your accent color</td></tr></tbody></table><p>One color covers every drawing tool. If you have never changed it, it follows the accent color you picked in the Home tab; once you set it explicitly it stops tracking the accent and stays where you put it.</p><h2 id="drawing-tools" tabindex="-1">Drawing tools <a class="header-anchor" href="#drawing-tools" aria-label="Permalink to &quot;Drawing tools&quot;">​</a></h2><p>Charts in the <a href="/manual/en/tools/analyzer.html">Analyzer</a> and in fullscreen chart views support five drawing tools. Each is bound to a single key, and each binding is editable here.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it draws</th><th>Default key</th></tr></thead><tbody><tr><td><strong>Horizontal ray key</strong></td><td>A horizontal ray at a chosen price</td><td><kbd>H</kbd></td></tr><tr><td><strong>Trend line key</strong></td><td>A two-point trend line</td><td><kbd>T</kbd></td></tr><tr><td><strong>Rectangle key</strong></td><td>A rectangle / box region</td><td><kbd>B</kbd></td></tr><tr><td><strong>Pencil key</strong></td><td>Freehand drawing</td><td><kbd>P</kbd></td></tr><tr><td><strong>Dissolving pencil key</strong></td><td>Freehand drawing that fades away on its own</td><td><kbd>F</kbd></td></tr></tbody></table><p>To rebind one, click the key button next to it — it switches to <code>Press a key…</code> — then press the key you want. Press <kbd>Esc</kbd> to cancel without changing it.</p><p>A few rules the capture enforces:</p><ul><li>Only letters and digits are accepted for the five drawing tools.</li><li>Modifier combinations are rejected — pressing <kbd>Ctrl</kbd>+<kbd>H</kbd> does nothing, the binding must be a bare key.</li><li>Bindings must be unique. If you pick a key that is already assigned to another tool, the capture is dismissed and nothing changes.</li></ul><p>Bindings are stored as physical key positions rather than characters, so they keep working if you switch keyboard layout or type in another language.</p><p>Drawings are saved per symbol <em>and</em> per exchange, so switching a chart from Bybit to Binance for the same ticker shows a different set of drawings.</p><h2 id="magnet" tabindex="-1">Magnet <a class="header-anchor" href="#magnet" aria-label="Permalink to &quot;Magnet&quot;">​</a></h2><p>Magnet snaps the point you are drawing to the nearest candle high or low, so rays and trend lines land exactly on a wick instead of near it.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Magnet</strong> mode</td><td><code>Hold</code> or <code>Toggle</code></td><td><code>Hold</code></td></tr><tr><td><strong>Magnet</strong> key</td><td>Key that activates it</td><td><kbd>Ctrl</kbd> (left)</td></tr></tbody></table><p>The two modes:</p><ul><li><strong>Hold</strong> — magnet is active only while the key is held down. Momentary.</li><li><strong>Toggle</strong> — pressing the key switches magnet on, pressing it again switches it off. The on/off state persists across restarts.</li></ul><p>Unlike the drawing tools, the magnet key <strong>may</strong> be a bare modifier — <kbd>Ctrl</kbd>, <kbd>Shift</kbd>, <kbd>Alt</kbd> or <kbd>Meta</kbd> — as well as a letter or digit. The default is left <kbd>Ctrl</kbd>. The same no-duplicates rule applies against the five drawing keys.</p><h2 id="what-is-not-here" tabindex="-1">What is <em>not</em> here <a class="header-anchor" href="#what-is-not-here" aria-label="Permalink to &quot;What is *not* here&quot;">​</a></h2><p>Colors that indicate a metric crossing a threshold are configured per tool, not globally, because the thresholds themselves are per tool:</p><ul><li>Monitor&#39;s NATR and % change level colors, outlines and background fills → <a href="/manual/en/tools/monitor.html#metric-colors">Monitor → Metric colors</a></li><li>Terminal&#39;s ladder, depth-bar and position colors → <a href="/manual/en/tools/terminal.html#appearance">Terminal → Appearance</a></li></ul>',24))])}const f=r(h,[["render",c]]);export{m as __pageData,f as default};
